import{_ as i,o as t,c as a,a7 as s}from"./chunks/framework.BJyR0VjM.js";const p=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/configuration.md","filePath":"documentation/configuration.md"}'),r={name:"documentation/configuration.md"};function n(l,e,o,h,d,g){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>YggUtils is configured through a single YAML file: <code>YggUtils.yml</code>, located in the same directory you run the JAR from.</p><h2 id="generating-the-config" tabindex="-1">Generating the Config <a class="header-anchor" href="#generating-the-config" aria-label="Permalink to “Generating the Config”">​</a></h2><p>If <code>YggUtils.yml</code> does not exist, YggUtils will create it automatically on first run and exit. The generated file contains empty placeholder values:</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">authserver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://auth.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">serverfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">example.jar</span></span></code></pre></div><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to “Fields”">​</a></h2><h3 id="authserver" tabindex="-1"><code>authserver</code> <a class="header-anchor" href="#authserver" aria-label="Permalink to “authserver”">​</a></h3><p><strong>Type:</strong> <code>string</code><br><strong>Required:</strong> Yes</p><p>The root URL of your Yggdrasil-compatible authentication server. This value is passed directly to authlib-injector as the agent argument.</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">authserver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://littleskin.cn</span></span></code></pre></div><p>authlib-injector will query this URL for API metadata and use it to redirect all of Minecraft&#39;s authentication traffic.</p><h3 id="serverfile" tabindex="-1"><code>serverfile</code> <a class="header-anchor" href="#serverfile" aria-label="Permalink to “serverfile”">​</a></h3><p><strong>Type:</strong> <code>string</code><br><strong>Required:</strong> Yes</p><p>The filename of the Minecraft server JAR to launch, relative to the working directory.</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">serverfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">server.jar</span></span></code></pre></div><p>YggUtils checks that this file exists before starting. If it does not exist, YggUtils will print an error and exit with code <code>1</code>.</p><h2 id="example-config" tabindex="-1">Example Config <a class="header-anchor" href="#example-config" aria-label="Permalink to “Example Config”">​</a></h2><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">authserver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://littleskin.cn</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">serverfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">server.jar</span></span></code></pre></div><h2 id="validation-rules" tabindex="-1">Validation Rules <a class="header-anchor" href="#validation-rules" aria-label="Permalink to “Validation Rules”">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Behaviour</th></tr></thead><tbody><tr><td>File does not exist</td><td>Config generated, YggUtils exits with code <code>0</code></td></tr><tr><td><code>authserver</code> is empty</td><td>Warning printed, YggUtils exits with code <code>0</code></td></tr><tr><td><code>serverfile</code> is empty</td><td>Warning printed, YggUtils exits with code <code>0</code></td></tr><tr><td><code>serverfile</code> points to a missing file</td><td>Error printed, YggUtils exits with code <code>1</code></td></tr></tbody></table><h2 id="reconfiguring" tabindex="-1">Reconfiguring <a class="header-anchor" href="#reconfiguring" aria-label="Permalink to “Reconfiguring”">​</a></h2><p>To change your auth server or server JAR, edit <code>YggUtils.yml</code> directly and restart YggUtils. To reset to defaults, delete the file and run YggUtils once to regenerate it.</p>`,22)])])}const k=i(r,[["render",n]]);export{p as __pageData,k as default};
